INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 3.099, 20026002, 20026, 190801, 53, "カリン", 2, -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 2.801, 20026003, 20026, 190801, 54, "カリン", 2, -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 3);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 0.0, 20026004, 20026, 190801, 54, "カリン", 2, -416.5, "報酬がもらえますよ！\nチェックしてみてください", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 4);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 0.0, 20026005, 20026, 190801, 57, "カリン", 1, -416.5, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 5);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (1, 5.506, 20026006, 20026, 190801, 55, "カリン", 2, -363.0, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 1);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 1.216, 20026007, 20026, 190801, 55, "カリン", 1, -363.0, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 2);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 1.539, 20026008, 20026, 190801, 56, "カリン", 1, -363.0, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 3);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES (2, 1.875, 20026009, 20026, 190801, 56, "カリン", 1, -363.0, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", "2030/01/01 14:59:59", 0.0, "2022/04/18 15:00:00", 4);
